[ExtensionOf(tableStr(WorkflowTrackingStatusTable))]
final class METWorkflowTrackingStatusTable_Extension
{
}

Method.Source:
/// <summary>
/// Retrieves the user who submitted the invoice to workflow.
/// </summary>
/// <returns>
/// A string that contains the user who submitted the invoice to workflow.
/// </returns>
[SysClientCacheDataMethod(true)]
public display UserIdStr getSubmittedByUserName()
{
    UserInfo userInfo;

    if (this.Originator)
    {
        select firstonly name from userInfo
            where userInfo.Id == this.Originator;
    }

    return (userInfo.name) ? userInfo.name : '';
}
